<script setup lang="ts">import { computed,ref } from 'vue';import { useAppStore } from '@/stores/app';import { financeMetrics,money,portfolioCost,portfolioValue } from '@/domain/finance';import AppModal from '@/components/AppModal.vue';import UiIcon from '@/components/UiIcon.vue';import type { TransactionType } from '@/domain/models';const store=useAppStore();const show=ref(false);const metrics=computed(()=>financeMetrics(store.data.finance));const type=ref<TransactionType>('expense');const amount=ref(0);const category=ref('Jedzenie');const account=ref('Konto główne');const note=ref('');const date=ref(new Date().toISOString().slice(0,10));const submit=()=>{store.addTransaction({type:type.value,amount:amount.value,category:category.value,account:account.value,note:note.value,date:date.value,location:''});show.value=false;amount.value=0;note.value=''};const invested=computed(()=>portfolioCost(store.data.finance.investments));const portfolio=computed(()=>portfolioValue(store.data.finance.investments))</script>
<template><section><div class="page-heading"><div><p class="kicker">CENTRUM FINANSÓW</p><h1>Finanse</h1><p>Kontroluj przepływy, cele i inwestycje.</p></div><button class="button primary" @click="show=true"><UiIcon name="Plus"/> Dodaj transakcję</button></div><div class="stats-grid"><article class="card stat"><div class="icon-box blue"><UiIcon name="ArrowDownLeft"/></div><div><p class="eyebrow">PRZYCHODY</p><strong>{{money(metrics.income)}}</strong><p class="muted">Wszystkie transakcje</p></div></article><article class="card stat"><div class="icon-box amber"><UiIcon name="ArrowUpRight"/></div><div><p class="eyebrow">WYDATKI</p><strong>{{money(metrics.expenses)}}</strong><p class="muted">Wszystkie transakcje</p></div></article><article class="card stat"><div class="icon-box green"><UiIcon name="TrendingUp"/></div><div><p class="eyebrow">PORTFEL</p><strong>{{money(portfolio)}}</strong><p class="muted" :class="{'positive':portfolio>=invested}">{{portfolio>=invested?'+':''}}{{money(portfolio-invested)}}</p></div></article></div><div class="content-grid"><article class="card span-2"><header class="section-head"><div><p class="eyebrow">HISTORIA</p><h2>Transakcje</h2></div></header><div class="table-wrap"><table><thead><tr><th>Data</th><th>Opis</th><th>Kategoria</th><th>Konto</th><th class="right">Kwota</th><th><span class="sr-only">Akcje</span></th></tr></thead><tbody><tr v-for="t in store.data.finance.transactions" :key="t.id"><td>{{new Date(t.date).toLocaleDateString('pl-PL')}}</td><td><b>{{t.note||'Bez opisu'}}</b></td><td><span class="tag">{{t.category}}</span></td><td>{{t.account}}</td><td class="right amount" :class="t.type">{{t.type==='income'?'+':'−'}}{{money(t.amount)}}</td><td><button class="icon-button danger" :aria-label="`Usuń ${t.note}`" @click="store.removeTransaction(t.id)"><UiIcon name="Trash2" :size="17"/></button></td></tr></tbody></table></div></article><aside class="stack"><article class="card"><header class="section-head"><h2>Cele</h2><button class="icon-button" aria-label="Dodaj cel"><UiIcon name="Plus"/></button></header><div v-for="goal in store.data.finance.goals" :key="goal.id" class="goal"><div><b>{{goal.name}}</b><span>{{money(goal.current)}} / {{money(goal.target)}}</span></div><progress :value="goal.current" :max="goal.target"/><small>{{Math.round(goal.current/goal.target*100)}}% · do {{new Date(goal.deadline).toLocaleDateString('pl-PL')}}</small></div></article><article class="card insight"><UiIcon name="Sparkles"/><div><b>Wskazówka</b><p>Utrzymujesz dodatni przepływ {{money(metrics.balance)}}. Rozważ automatyczne zasilenie celu.</p></div></article></aside></div><AppModal v-if="show" title="Nowa transakcja" @close="show=false"><form class="form" @submit.prevent="submit"><div class="segmented"><button type="button" :class="{active:type==='expense'}" @click="type='expense'">Wydatek</button><button type="button" :class="{active:type==='income'}" @click="type='income'">Przychód</button></div><label>Kwota<input v-model.number="amount" required min="0.01" step="0.01" type="number" inputmode="decimal"></label><div class="form-row"><label>Kategoria<select v-model="category"><option>Jedzenie</option><option>Mieszkanie</option><option>Transport</option><option>Rozrywka</option><option>Wynagrodzenie</option></select></label><label>Data<input v-model="date" required type="date"></label></div><label>Opis<input v-model.trim="note" maxlength="120" placeholder="Np. zakupy"></label><label>Konto<select v-model="account"><option>Konto główne</option><option>Karta</option><option>Gotówka</option></select></label><button class="button primary full" type="submit">Zapisz transakcję</button></form></AppModal></section></template>
